import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";

// ============================================================
//  🔒 Axios setup
// ============================================================
const api = axios.create();
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("adminToken");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

const API_BASE = process.env.REACT_APP_API_BASE || "";

// ============================================================
//  Categories
// ============================================================
const CATEGORIES = [
  { value: "general", label: "عمومی", icon: "🐾" },
  { value: "نژادها", label: "نژادها", icon: "🐕" },
  { value: "سلامت", label: "سلامت", icon: "❤️" },
  { value: "آموزش", label: "آموزش", icon: "📖" },
];

// ============================================================
//  Main Component
// ============================================================
export default function BlogManager() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("list"); // list | edit
  const [editingPost, setEditingPost] = useState(null);
  const [editLoadingId, setEditLoadingId] = useState(null); // ✅ NEW
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState("");

  const fetchPosts = useCallback(async () => {
    try {
      setLoading(true);
      let url = `${API_BASE}/admin/blog`;
      const params = new URLSearchParams();
      if (search) params.append("search", search);
      if (filterStatus) params.append("status", filterStatus);
      if (params.toString()) url += "?" + params.toString();

      const res = await api.get(url);
      setPosts(res.data.posts || []);
    } catch (err) {
      console.error("Error:", err);
      alert("خطا در بارگذاری مقالات");
    } finally {
      setLoading(false);
    }
  }, [search, filterStatus]);

  useEffect(() => {
    fetchPosts();
  }, [fetchPosts]);

  const handleDelete = async (id, title) => {
    if (!window.confirm(`آیا مطمئن هستی که می‌خواهی «${title}» رو حذف کنی؟`)) return;

    try {
      await api.delete(`${API_BASE}/admin/blog/${id}`);
      alert("✅ مقاله حذف شد");
      fetchPosts();
    } catch (err) {
      alert("❌ خطا در حذف");
    }
  };

  const handlePublishToggle = async (post) => {
    try {
      if (post.status === "published") {
        await api.put(`${API_BASE}/admin/blog/${post.id}/unpublish`);
        alert("✅ انتشار لغو شد");
      } else {
        await api.put(`${API_BASE}/admin/blog/${post.id}/publish`);
        alert("✅ مقاله منتشر شد");
      }
      fetchPosts();
    } catch (err) {
      alert("❌ خطا در تغییر وضعیت");
    }
  };

  // ============================================================
  //  ✅ FIX: گرفتن مقاله‌ی کامل (با content) از سرور
  //  لیست API فقط خلاصه رو برمی‌گردونه، پس باید detail صدا زده بشه
  // ============================================================
  const handleEdit = async (post) => {
    try {
      setEditLoadingId(post.id);
      const res = await api.get(`${API_BASE}/admin/blog/${post.id}`);
      setEditingPost(res.data);
      setView("edit");
    } catch (err) {
      console.error("خطا در بارگذاری مقاله:", err);
      alert("❌ خطا در بارگذاری مقاله. لطفاً دوباره تلاش کن.");
    } finally {
      setEditLoadingId(null);
    }
  };

  const handleNew = () => {
    setEditingPost(null);
    setView("edit");
  };

  const handleBack = () => {
    setView("list");
    setEditingPost(null);
    fetchPosts();
  };

  // ============================================================
  //  LIST VIEW
  // ============================================================
  if (view === "list") {
    return (
      <div className="p-4 md:p-8" dir="rtl">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-2xl font-black text-miko-dark">📝 مدیریت بلاگ</h1>
            <p className="text-sm text-miko-dark/60 mt-1">مقالات بلاگ سایت میکو</p>
          </div>
          <button
            onClick={handleNew}
            className="bg-miko-rust text-white font-bold px-5 py-3 rounded-xl hover:bg-miko-pumpkin transition-colors shadow-md flex items-center gap-2"
          >
            <span className="text-lg">+</span> مقاله جدید
          </button>
        </div>

        {/* Filters */}
        <div className="flex flex-col md:flex-row gap-3 mb-6">
          <input
            type="text"
            placeholder="جستجو در عناوین..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="flex-1 px-4 py-2.5 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-sm text-miko-dark"
          />
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2.5 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-sm text-miko-dark"
          >
            <option value="">همه وضعیت‌ها</option>
            <option value="published">منتشرشده</option>
            <option value="draft">پیش‌نویس</option>
          </select>
        </div>

        {/* Posts Table */}
        {loading ? (
          <div className="text-center py-20">
            <div className="inline-block w-10 h-10 border-4 border-miko-carrot/30 border-t-miko-rust rounded-full animate-spin"></div>
          </div>
        ) : posts.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-2xl border border-miko-carrot/20">
            <div className="text-5xl mb-4">📭</div>
            <p className="text-miko-dark/60 mb-4">هنوز مقاله‌ای ساخته نشده</p>
            <button
              onClick={handleNew}
              className="bg-miko-rust text-white font-bold px-6 py-3 rounded-xl hover:bg-miko-pumpkin transition-colors"
            >
              ساخت اولین مقاله
            </button>
          </div>
        ) : (
          <div className="bg-white rounded-2xl border border-miko-carrot/20 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-miko-cream text-miko-dark/70">
                    <th className="text-right p-4 font-bold">عنوان</th>
                    <th className="text-right p-4 font-bold hidden md:table-cell">دسته</th>
                    <th className="text-right p-4 font-bold">وضعیت</th>
                    <th className="text-right p-4 font-bold hidden md:table-cell">بازدید</th>
                    <th className="text-right p-4 font-bold hidden lg:table-cell">تاریخ</th>
                    <th className="text-right p-4 font-bold">عملیات</th>
                  </tr>
                </thead>
                <tbody>
                  {posts.map((post) => (
                    <tr
                      key={post.id}
                      className="border-t border-miko-carrot/10 hover:bg-miko-cream/50 transition-colors"
                    >
                      <td className="p-4">
                        <div className="font-bold text-miko-dark">{post.title}</div>
                        <div className="text-xs text-miko-dark/50 mt-0.5">/{post.slug}</div>
                      </td>
                      <td className="p-4 hidden md:table-cell">
                        <span className="text-xs bg-miko-cream text-miko-rust px-2 py-1 rounded border border-miko-carrot/20">
                          {post.category}
                        </span>
                      </td>
                      <td className="p-4">
                        <button
                          onClick={() => handlePublishToggle(post)}
                          className={`text-xs font-bold px-3 py-1.5 rounded-lg transition-all ${
                            post.status === "published"
                              ? "bg-green-100 text-green-700 hover:bg-green-200"
                              : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                          }`}
                        >
                          {post.status === "published" ? "✅ منتشرشده" : "📝 پیش‌نویس"}
                        </button>
                      </td>
                      <td className="p-4 hidden md:table-cell text-miko-dark/60">
                        {post.views_count || 0}
                      </td>
                      <td className="p-4 hidden lg:table-cell text-miko-dark/60 text-xs">
                        {post.published_at
                          ? new Intl.DateTimeFormat("fa-IR", {
                              day: "numeric",
                              month: "short",
                              year: "numeric",
                            }).format(new Date(post.published_at))
                          : "—"}
                      </td>
                      <td className="p-4">
                        <div className="flex gap-2">
                          <button
                            onClick={() => handleEdit(post)}
                            disabled={editLoadingId !== null}
                            className="text-xs bg-miko-cream text-miko-rust border border-miko-carrot/30 px-3 py-1.5 rounded-lg hover:bg-miko-rust hover:text-white transition-all font-bold disabled:opacity-50 disabled:cursor-wait"
                          >
                            {editLoadingId === post.id ? "در حال بارگذاری…" : "ویرایش"}
                          </button>
                          <button
                            onClick={() => handleDelete(post.id, post.title)}
                            className="text-xs bg-rose-50 text-rose-600 border border-rose-200 px-3 py-1.5 rounded-lg hover:bg-rose-500 hover:text-white transition-all font-bold"
                          >
                            حذف
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    );
  }

  // ============================================================
  //  EDIT VIEW
  //  ✅ key باعث می‌شه PostEditor با هر مقاله از نو mount بشه
  //  تا useState همیشه مقدار تازه بگیره (نه مقدار قبلی)
  // ============================================================
  return (
    <PostEditor
      key={editingPost?.id || "new"}
      post={editingPost}
      onBack={handleBack}
    />
  );
}


// ============================================================
//  PostEditor Component
// ============================================================
function PostEditor({ post, onBack }) {
  const [formData, setFormData] = useState({
    title: post?.title || "",
    slug: post?.slug || "",
    excerpt: post?.excerpt || "",
    content: post?.content || "",
    featured_image: post?.featured_image || "",
    category: post?.category || "general",
    // ✅ FIX: هم آرایه هم رشته رو پشتیبانی می‌کنه
    tags: Array.isArray(post?.tags)
      ? post.tags.join(", ")
      : (post?.tags || ""),
    meta_description: post?.meta_description || "",
    status: post?.status || "draft",
  });
  const [saving, setSaving] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Auto-generate slug from title
  const handleTitleChange = (e) => {
    const title = e.target.value;
    setFormData({ ...formData, title });
    if (!post && !formData.slug) {
      // Auto-generate slug for new posts
      const slug = title
        .trim()
        .toLowerCase()
        .replace(/\s+/g, "-")
        .replace(/[^\w\-]/g, "")
        .substring(0, 200);
      setFormData((prev) => ({ ...prev, title, slug }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (formData.title.length < 5) {
      alert("عنوان حداقل ۵ کاراکتر باید باشد");
      return;
    }

    // ✅ SAFETY: قبل از ذخیره، تأیید کن متن مقاله خالی نشده
    if (post && !formData.content.trim()) {
      const ok = window.confirm(
        "⚠️ متن مقاله خالی است. آیا مطمئنی که می‌خواهی بدون متن ذخیره کنی؟\n\n(اگر اشتباهی پاک شده، انصراف بده و صفحه را رفرش کن)"
      );
      if (!ok) return;
    }

    setSaving(true);
    try {
      const payload = { ...formData };
      // Convert tags string to comma-separated
      payload.tags = formData.tags;

      if (post) {
        await api.put(`${API_BASE}/admin/blog/${post.id}`, payload);
        alert("✅ مقاله ویرایش شد");
      } else {
        await api.post(`${API_BASE}/admin/blog`, payload);
        alert("✅ مقاله ساخته شد");
      }
      onBack();
    } catch (err) {
      const msg = err.response?.data?.detail || "خطا در ذخیره";
      alert("❌ " + msg);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="p-4 md:p-8 max-w-4xl mx-auto" dir="rtl">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <button
            onClick={onBack}
            className="text-sm text-miko-dark/60 hover:text-miko-rust mb-2 flex items-center gap-1"
          >
            ← بازگشت به لیست
          </button>
          <h1 className="text-2xl font-black text-miko-dark">
            {post ? "✏️ ویرایش مقاله" : "📝 مقاله جدید"}
          </h1>
        </div>
      </div>

      {/* Form */}
      <form onSubmit={handleSubmit} className="space-y-5">
        {/* Title & Slug */}
        <div className="grid md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-bold text-miko-dark mb-2">
              عنوان مقاله *
            </label>
            <input
              type="text"
              name="title"
              value={formData.title}
              onChange={handleTitleChange}
              required
              className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust focus:ring-2 focus:ring-miko-rust/20 text-miko-dark"
              placeholder="مثلاً: بهترین غذای سگ‌های پاگ"
            />
          </div>
          <div>
            <label className="block text-sm font-bold text-miko-dark mb-2">
              آدرس (slug) *
            </label>
            <input
              type="text"
              name="slug"
              value={formData.slug}
              onChange={handleChange}
              required
              dir="ltr"
              className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust focus:ring-2 focus:ring-miko-rust/20 text-miko-dark text-left"
              placeholder="best-food-for-pug-dogs"
            />
          </div>
        </div>

        {/* Category & Status */}
        <div className="grid md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-bold text-miko-dark mb-2">
              دسته‌بندی
            </label>
            <select
              name="category"
              value={formData.category}
              onChange={handleChange}
              className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-miko-dark"
            >
              {CATEGORIES.map((cat) => (
                <option key={cat.value} value={cat.value}>
                  {cat.icon} {cat.label}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-bold text-miko-dark mb-2">
              وضعیت
            </label>
            <select
              name="status"
              value={formData.status}
              onChange={handleChange}
              className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-miko-dark"
            >
              <option value="draft">📝 پیش‌نویس</option>
              <option value="published">✅ منتشرشده</option>
            </select>
          </div>
        </div>

        {/* Featured Image */}
        <div>
          <label className="block text-sm font-bold text-miko-dark mb-2">
            آدرس تصویر شاخص (اختیاری)
          </label>
          <input
            type="text"
            name="featured_image"
            value={formData.featured_image}
            onChange={handleChange}
            dir="ltr"
            className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-miko-dark text-left"
            placeholder="https://example.com/image.jpg (خالی = گرادیانت)"
          />
          <p className="text-xs text-miko-dark/50 mt-1">
            اگه خالی بذاری، یک گرادیانت رنگی با ایموجون نمایش داده می‌شه
          </p>
        </div>

        {/* Excerpt */}
        <div>
          <label className="block text-sm font-bold text-miko-dark mb-2">
            خلاصه (excerpt)
          </label>
          <textarea
            name="excerpt"
            value={formData.excerpt}
            onChange={handleChange}
            rows={2}
            className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust focus:ring-2 focus:ring-miko-rust/20 text-miko-dark resize-none"
            placeholder="خلاصه‌ی کوتاه مقاله (در لیست مقالات نمایش داده می‌شه)"
          />
        </div>

        {/* Content */}
        <div>
          <label className="block text-sm font-bold text-miko-dark mb-2">
            محتوای مقاله *
          </label>
          <textarea
            name="content"
            value={formData.content}
            onChange={handleChange}
            rows={20}
            required
            className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust focus:ring-2 focus:ring-miko-rust/20 text-miko-dark text-sm leading-relaxed resize-y font-mono"
            placeholder={`متن مقاله...

راهنمای فرمت:
## تیتر
متن پاراگراف
**متن بولد**
- مورد لیست`}
          />
          <div className="mt-2 bg-miko-cream rounded-xl p-3 border border-miko-carrot/20 text-xs text-miko-dark/70 space-y-1">
            <p className="font-bold text-miko-dark">📖 راهنمای فرمت:</p>
            <p><code className="bg-white px-2 rounded">## متن</code> → تیتر</p>
            <p><code className="bg-white px-2 rounded">**متن**</code> → <strong>بولد</strong></p>
            <p><code className="bg-white px-2 rounded">- متن</code> → آیتم لیست</p>
            <p><code className="bg-white px-2 rounded">خط خالی</code> → پاراگراف جدید</p>
          </div>
        </div>

        {/* Tags */}
        <div>
          <label className="block text-sm font-bold text-miko-dark mb-2">
            برچسب‌ها (با کاما جدا کنید)
          </label>
          <input
            type="text"
            name="tags"
            value={formData.tags}
            onChange={handleChange}
            className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-miko-dark"
            placeholder="پاگ, سگ‌های کوچک, تغذیه"
          />
        </div>

        {/* Meta Description */}
        <div>
          <label className="block text-sm font-bold text-miko-dark mb-2">
            توضیحات متا (SEO)
          </label>
          <input
            type="text"
            name="meta_description"
            value={formData.meta_description}
            onChange={handleChange}
            maxLength={300}
            className="w-full px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust text-miko-dark"
            placeholder="توضیحات کوتاه برای موتورهای جستجو (اختیاری)"
          />
        </div>

        {/* Buttons */}
        <div className="flex gap-3 pt-4">
          <button
            type="submit"
            disabled={saving}
            className="flex-1 bg-miko-rust text-white font-bold py-4 rounded-xl hover:bg-miko-pumpkin transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {saving ? "در حال ذخیره..." : post ? "💾 ذخیره تغییرات" : "✅ ساخت مقاله"}
          </button>
          <button
            type="button"
            onClick={onBack}
            className="px-6 bg-miko-cream text-miko-dark border border-miko-carrot/30 font-bold rounded-xl hover:bg-miko-carrot/10 transition-colors"
          >
            انصراف
          </button>
        </div>
      </form>
    </div>
  );
}